// Cosine-curve colour ramp (ported from Python original):
// 0 → deep purple/blue, 50 → bright red-orange, 100 → flag green
function pctColor(pct) {
  const v = Math.max(0, Math.min(100, pct ?? 0));
  const PI = Math.PI;
  const cos = Math.cos;

  let r, g, b;

  // Red channel
  if (v <= 25)       r = 128 + (255 - 128) * (1 - cos(PI * v / 25)) / 2;
  else if (v <= 50)  r = 255;
  else if (v <= 75)  r = 255 * (1 - (1 - cos(PI * (v - 50) / 25)) / 2);
  else               r = 0;

  // Green channel
  if (v <= 25)       g = 0;
  else if (v <= 50)  g = 220 * (1 - cos(PI * (v - 25) / 25)) / 2;
  else if (v <= 75)  g = 220 + (255 - 220) * (1 - cos(PI * (v - 50) / 25)) / 2;
  else               g = 255 - (255 - 90) * (1 - cos(PI * (v - 75) / 25)) / 2;

  // Blue channel
  if (v <= 25)       b = 255 * (1 - (1 - cos(PI * v / 25)) / 2);
  else               b = 0;

  return `rgb(${Math.round(r)},${Math.round(g)},${Math.round(b)})`;
}
