function zscore(arr) {
  const valid = arr.filter(v => v != null && isFinite(v));
  if (valid.length < 2) return arr.map(() => 0);
  const mean = valid.reduce((a, b) => a + b, 0) / valid.length;
  const std = Math.sqrt(valid.reduce((a, b) => a + (b - mean) ** 2, 0) / valid.length);
  if (std === 0) return arr.map(() => 0);
  return arr.map(v => (v == null || !isFinite(v)) ? null : (v - mean) / std);
}

function norm0100(arr) {
  const valid = arr.filter(v => v != null && isFinite(v));
  if (valid.length < 2) return arr.map(() => 50);
  const lo = Math.min(...valid), hi = Math.max(...valid);
  if (lo === hi) return arr.map(() => 50);
  return arr.map(v => (v == null || !isFinite(v)) ? null : ((v - lo) / (hi - lo)) * 100);
}

function percentileRank(values, idx, negate = false) {
  const valid = values.map((v, i) => ({ v: parseFloat(v), i })).filter(x => isFinite(x.v));
  if (valid.length <= 1) return null;
  const sorted = [...valid].sort((a, b) => negate ? a.v - b.v : b.v - a.v);
  const rank = sorted.findIndex(x => x.i === idx);
  if (rank === -1) return null;
  return Math.round(((valid.length - 1 - rank) / (valid.length - 1)) * 100);
}

function computeDerived(rows) {
  const n = rows.length;
  const col = (name) => rows.map(r => parseFloat(r[name]));
  const safeDiv = (a, b) => a.map((av, i) => (b[i] && b[i] !== 0) ? av / b[i] : null);

  const xg = col("xG"), goals = col("Goals"), shots = col("Shots"), min = col("Minutes played");
  const npxg = xg.map((v, i) => isFinite(v) ? v : null);
  const npxgP90 = npxg.map((v, i) => (v != null && isFinite(min[i]) && min[i] > 0) ? (v / min[i]) * 90 : null);
  const npxgShot = safeDiv(npxg, shots.map(v => isFinite(v) && v > 0 ? v : null));
  const gxg = goals.map((g, i) => (isFinite(g) && isFinite(xg[i])) ? g - xg[i] : null);

  const makeComposite = (weights) => {
    const parts = Object.entries(weights)
      .filter(([k]) => rows[0] && rows[0][k] !== undefined)
      .map(([k, w]) => {
        let vals = col(k);
        if (k.includes("%") && Math.max(...vals.filter(isFinite)) > 1) vals = vals.map(v => isFinite(v) ? v / 100 : null);
        return [zscore(vals), w];
      });
    if (!parts.length) return new Array(n).fill(null);
    const totW = parts.reduce((s, [, w]) => s + w, 0);
    return rows.map((_, i) => {
      const valid = parts.filter(([z]) => z[i] != null);
      if (!valid.length) return null;
      return valid.reduce((s, [z, w]) => s + z[i] * w, 0) / totW;
    });
  };

  const creativity = makeComposite({ "Smart passes per 90": 1, "Through passes per 90": 0.8, "Passes to penalty area per 90": 0.6, "Accurate smart passes, %": 0.8, "Accurate through passes, %": 0.7, "Key passes per 90": 0.9, "xA per 90": 0.9 });
  const xgBuildup = makeComposite({ "xA per 90": 1, "Key passes per 90": 0.9, "Passes to penalty area per 90": 0.8, "Deep completions per 90": 0.7, "Shot assists per 90": 0.7, "Second assists per 90": 0.6 });
  const progression = makeComposite({ "Progressive passes per 90": 1, "Progressive runs per 90": 0.9, "Dribbles per 90": 0.7, "Accelerations per 90": 0.5, "Accurate progressive passes, %": 0.8 });
  const defence = makeComposite({ "Successful defensive actions per 90": 1.5, "PAdj Interceptions": 1.5, "Shots blocked per 90": 1, "PAdj Sliding tackles": 1, "Defensive duels won, %": 2, "Aerial duels won, %": 1 });
  const involvement = makeComposite({ "Passes per 90": 0.2, "Received passes per 90": 0.15, "Defensive duels per 90": 0.1, "PAdj Interceptions": 0.1, "Touches in box per 90": 0.1 });
  const passingQuality = makeComposite({ "Passes to final third per 90": 0.4, "Accurate passes to final third, %": 0.4, "Forward passes per 90": 0.3, "Accurate forward passes, %": 0.3, "Long passes per 90": 0.15, "Accurate long passes, %": 0.15 });
  const finishing = makeComposite({ "Goal conversion, %": 0.4, "Shots on target, %": 0.3, "G-xG": 0.2, "npxG per Shot": 0.1 });
  const boxThreat = makeComposite({ "npxG per 90": 1, "Touches in box per 90": 0.8 });
  const discipline = (() => {
    const fouls = col("Fouls per 90"), yc = col("Yellow cards per 90"), rc = col("Red cards per 90");
    const pen2 = fouls.map((f, i) => (isFinite(f) ? f : 0) + (isFinite(yc[i]) ? yc[i] * 2 : 0) + (isFinite(rc[i]) ? rc[i] * 4 : 0));
    const z = zscore(pen2);
    return z.map(v => v != null ? -v : null);
  })();
  const aerialThreat = makeComposite({ "Head goals per 90": 0.4, "Aerial duels per 90": 0.3, "Aerial duels won, %": 0.3 });
  const aerialDefence = makeComposite({ "Aerial duels per 90": 0.3, "Aerial duels won, %": 0.4, "PAdj Interceptions": 0.2, "Shots blocked per 90": 0.1 });

  const poachingRaw = rows.map((r, i) => {
    const npxgPerShotVal = parseFloat(r["npxG per Shot"]) || 0;
    const goalConvVal = (parseFloat(r["Goal conversion, %"]) || 0) / 100;
    const touchesBoxVal = parseFloat(r["Touches in box per 90"]) || 0;
    const receivedPassesVal = parseFloat(r["Received passes per 90"]) || 0;
    const nonPenaltyGoals = (parseFloat(r["Goals"]) - parseFloat(r["Penalties taken"])) / (parseFloat(r["Minutes played"]) / 90) || 0;
    return (npxgPerShotVal * 0.35) + (goalConvVal * 0.30) + (touchesBoxVal * 0.20) + (nonPenaltyGoals * 0.15) - (receivedPassesVal * 0.10);
  });
  const poachingZ = zscore(poachingRaw);
  const poachingNorm = poachingZ.map(v => v != null ? Math.min(100, Math.max(0, (v + 3) / 6 * 100)) : 50);
  
  const offProd = rows.map((r) => {
    return (parseFloat(r["Successful attacking actions per 90"]) || 0) +
      (parseFloat(r["xG per 90"]) || 0) +
      (parseFloat(r["xA per 90"]) || 0) +
      (parseFloat(r["Key passes per 90"]) || 0) +
      (parseFloat(r["Deep completions per 90"]) || 0) +
      (parseFloat(r["Progressive runs per 90"]) || 0) * 0.6;
  });
  const defProd = rows.map((r) => {
    return (parseFloat(r["Successful defensive actions per 90"]) || 0) +
      (parseFloat(r["Defensive duels per 90"]) || 0) * ((parseFloat(r["Defensive duels won, %"]) || 0) / 100) +
      (parseFloat(r["Aerial duels per 90"]) || 0) * ((parseFloat(r["Aerial duels won, %"]) || 0) / 100) +
      (parseFloat(r["PAdj Sliding tackles"]) || 0) +
      (parseFloat(r["PAdj Interceptions"]) || 0);
  });

  const distKm = rows.map(r => {
    const d = parseFloat(r["Distance P90"]);
    return isFinite(d) ? (d > 2000 ? d / 1000 : d) : null;
  });
  const hiKm = rows.map(r => {
    const hi = parseFloat(r["HI Distance P90"]) || 0;
    const run = parseFloat(r["Running Distance P90"]) || 0;
    const s = hi + run;
    return s > 2000 ? s / 1000 : s || null;
  });
  const expEvt = rows.map(r => {
    return (parseFloat(r["HSR Count P90"]) || 0) + (parseFloat(r["Sprint Count P90"]) || 0) +
      (parseFloat(r["Explosive Acceleration to HSR Count P90"]) || 0) + (parseFloat(r["Explosive Acceleration to Sprint Count P90"]) || 0) || null;
  });

  const derived = {
    "npxG per 90": norm0100(npxgP90),
    "npxG per Shot": norm0100(npxgShot),
    "G-xG": norm0100(gxg),
    "Box Threat": norm0100(boxThreat),
    "xG Buildup": norm0100(xgBuildup),
    "Creativity": norm0100(creativity),
    "Progression": norm0100(progression),
    "Defence": norm0100(defence),
    "Involvement": norm0100(involvement),
    "Discipline": norm0100(discipline),
    "Finishing": norm0100(finishing),
    "Passing Quality": norm0100(passingQuality),
    "Aerial Threat": norm0100(aerialThreat),
    "Aerial Defence": norm0100(aerialDefence),
    "Poaching": poachingNorm,
    "Work Rate Offensive": norm0100(offProd.map((v, i) => distKm[i] ? v / distKm[i] : null)),
    "Work Rate Defensive": norm0100(defProd.map((v, i) => distKm[i] ? v / distKm[i] : null)),
    "Offensive Intensity": norm0100(offProd.map((v, i) => hiKm[i] ? v / hiKm[i] : null)),
    "Defensive Intensity": norm0100(defProd.map((v, i) => hiKm[i] ? v / hiKm[i] : null)),
    "Offensive Explosion": norm0100(offProd.map((v, i) => expEvt[i] ? v / expEvt[i] : null)),
    "Defensive Explosion": norm0100(defProd.map((v, i) => expEvt[i] ? v / expEvt[i] : null)),
  };

  return rows.map((r, i) => {
    const out = { ...r };
    for (const [k, arr] of Object.entries(derived)) {
      if (arr[i] != null) out[k] = arr[i];
    }
    return out;
  });
}

function parseCSV(text) {
  const lines = text.trim().split("\n");
  if (!lines.length) return [];
  const headers = lines[0].split("\t").map(h => h.trim());
  return lines.slice(1).map(line => {
    const vals = line.split("\t");
    const row = {};
    headers.forEach((h, i) => { row[h] = vals[i]?.trim() ?? ""; });
    return row;
  });
}

